+      final watchdog =
+          (jobs['watchdog'] as YamlMap)['needs'].toString();
+      expect(watchdog, isNot(contains('installer-portability')),
+          reason: 'the watchdog waits on the always-on longest legs; '
+              'path-triggered legs are not on that list (exzone/locksmoke '
+              'precedent)');
+    });
+  });
+}

