+  'anthropic': ['claude-sonnet-4-5', 'claude-opus-4', 'claude-haiku-4'],
+  'google': ['gemini-2.5-pro', 'gemini-2.0-flash'],
+  'openai': ['gpt-4o-mini', 'gpt-4o', 'gpt-4.1-mini'],
