          .toList();
      expect(
        cases.map((c) => c.id).toList(),
        expectedProviders,
        reason: 'AC6: provider menu == catalog names — openrouter first, '
            'then catalog order, custom last. Stale menus ship stale '
            'providers on every fresh download (the #1596 audit finding).',
