/// Formats a token count as a compact preset label (`4K`, `16K`, `1M`).
String formatTokenPreset(int tokens) {
  if (tokens >= 1048576 && tokens % 1048576 == 0) {
    return '${tokens ~/ 1048576}M';
  }
  if (tokens >= 1024 && tokens % 1024 == 0) {
    return '${tokens ~/ 1024}K';
