bool _have(String bin) =>
    Process.runSync('sh', ['-c', 'command -v $bin']).exitCode == 0;

final _ansi = RegExp('\x1b\\[[0-9;]*[A-Za-z]');

String _clean(String s) => s.replaceAll(_ansi, '');

