    /// (recommended), then the catalog order, `custom` last.
    final expectedProviders = [
      'openrouter',
      ...providerCatalog.keys.where((id) => id != 'openrouter'),
      'custom',
    ];

    test('the provider case list equals the catalog (+ custom last)', () {
      final cases = providerCase
          .allMatches(setup)
